/**
 * @summary List public careers jobs by company
 */
export type getCareersCompanyIdJobsResponse200 = {
  data: GetCareersCompanyIdJobs200
  status: 200
}

export type getCareersCompanyIdJobsResponse404 = {
  data: GetCareersCompanyIdJobs404
  status: 404
}
    
export type getCareersCompanyIdJobsResponseSuccess = (getCareersCompanyIdJobsResponse200) & {
  headers: Headers;
};
export type getCareersCompanyIdJobsResponseError = (getCareersCompanyIdJobsResponse404) & {
  headers: Headers;
};

export type getCareersCompanyIdJobsResponse = (getCareersCompanyIdJobsResponseSuccess | getCareersCompanyIdJobsResponseError)

export const getGetCareersCompanyIdJobsUrl = (companyId: string,
    params?: GetCareersCompanyIdJobsParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : value.toString())
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/careers/${companyId}/jobs?${stringifiedParams}` : `/careers/${companyId}/jobs`
}

export const getCareersCompanyIdJobs = async (companyId: string,
    params?: GetCareersCompanyIdJobsParams, options?: RequestInit): Promise<getCareersCompanyIdJobsResponse> => {
  
  return coployFetch<getCareersCompanyIdJobsResponse>(getGetCareersCompanyIdJobsUrl(companyId,params),
  {      
    ...options,
    method: 'GET'
    
    
  }
);}



